{
  // Test mode, as the Firebase console creates it: anyone reads and writes everything.
  "rules": {
    ".read": true,
    ".write": true
  }
}

{
  /* Locked mode: only the Admin SDKs get in. */
  "rules": {
    ".read": false,
    ".write": false
  }
}

{
  "rules": {
    // Any signed-in user, nobody else.
    ".read": "auth != null",
    ".write": "auth !== null"
  }
}

{
  "rules": {
    "users": {
      "$uid": {
        ".read": "auth != null && auth.uid == $uid",
        ".write": "auth != null && auth.uid == $uid",
        ".validate": "newData.hasChildren(['name', 'age'])",
        "name": {
          ".validate": "newData.isString() && newData.val().length > 0 && newData.val().length <= 50"
        },
        "age": {
          ".validate": "newData.isNumber() && newData.val() >= 13 && newData.val() < 150"
        },
        "bio": {
          ".validate": "newData.isString() && newData.val().length < 500"
        },
        "$other": {
          ".validate": false
        }
      }
    },
    "publicProfiles": {
      ".read": true,
      "$uid": {
        ".write": "auth.uid === $uid",
        "displayName": { ".validate": "newData.isString()" }
      }
    }
  }
}

{
  "rules": {
    "rooms": {
      ".read": "auth != null",
      "$roomId": {
        // Only the room's creator edits the room itself.
        ".write": "auth != null && (!data.exists() || data.child('owner').val() === auth.uid)",
        ".validate": "newData.hasChildren(['name', 'owner'])",
        "name": { ".validate": "newData.isString() && newData.val().length <= 40" },
        "owner": { ".validate": "newData.val() === auth.uid || newData.val() === data.val()" }
      }
    },
    "members": {
      "$roomId": {
        ".read": "auth != null && data.child(auth.uid).exists()",
        "$uid": {
          ".write": "auth.uid === $uid || root.child('rooms/' + $roomId + '/owner').val() === auth.uid",
          ".validate": "newData.isBoolean()"
        }
      }
    },
    "messages": {
      "$roomId": {
        ".read": "root.child('members/' + $roomId + '/' + auth.uid).exists()",
        ".indexOn": ["ts"],
        "$msgId": {
          ".write": "!data.exists() && root.child('members').child($roomId).child(auth.uid).val() === true",
          ".validate": "newData.hasChildren(['uid', 'text', 'ts'])",
          "uid": { ".validate": "newData.val() === auth.uid" },
          "text": { ".validate": "newData.isString() && newData.val().length > 0 && newData.val().length <= 500" },
          "ts": { ".validate": "newData.isNumber() && newData.val() <= now" },
          "$other": { ".validate": false }
        }
      }
    }
  }
}

{
  "rules": {
    "todos": {
      "$uid": {
        ".read": "$uid === auth.uid",
        ".write": "$uid === auth.uid",
        ".indexOn": ["done", "createdAt"],
        "$todoId": {
          ".validate": "newData.hasChildren(['title', 'done'])",
          "title": { ".validate": "newData.isString() && newData.val().length < 200" },
          "done": { ".validate": "newData.isBoolean()" },
          "createdAt": { ".validate": "newData.isNumber()" },
          "$other": { ".validate": false }
        }
      }
    }
  }
}

{
  "rules": {
    "admins": {
      ".read": "root.child('admins').child(auth.uid).val() == true",
      ".write": false
    },
    "posts": {
      ".read": true,
      ".indexOn": ["author", "publishedAt"],
      "$postId": {
        // Authors create their posts and edit them; admins edit anything.
        ".write": "auth != null && ((!data.exists() && newData.child('author').val() == auth.uid) || data.child('author').val() == auth.uid || root.child('admins/' + auth.uid).val() == true)",
        ".validate": "newData.hasChildren(['title', 'body', 'author'])",
        "title": { ".validate": "newData.isString() && newData.val().length >= 3" },
        "body": { ".validate": "newData.isString()" },
        "author": { ".validate": "newData.val() == data.val() || !data.exists()" },
        "publishedAt": { ".validate": "newData.isNumber()" },
        "comments": {
          "$commentId": {
            ".write": "auth != null && !data.exists() && newData.child('by').val() == auth.uid",
            ".validate": "newData.child('text').isString()"
          }
        }
      }
    }
  }
}

{
  "rules": {
    "config": {
      ".read": "auth != null",
      ".write": "auth.token.admin === true"
    },
    "articles": {
      ".read": true,
      "$id": {
        ".write": "auth.token.role === 'editor' || auth.token.admin === true",
        "status": {
          // Only admins publish.
          ".validate": "newData.val() === 'draft' || (newData.val() === 'published' && auth.token.admin === true)"
        }
      }
    },
    "billing": {
      "$uid": {
        ".read": "auth.uid === $uid && auth.token.subscriptionStatus == 'active'",
        ".write": false
      }
    }
  }
}

{
  "rules": {
    // Staff only: a verified address at the company's domain.
    ".read": "auth != null && auth.token.email_verified == true && auth.token.email.matches(/.*@example\\.com$/)",
    "staff": {
      "$uid": {
        ".write": "auth.uid == $uid && auth.token.email.endsWith('@example.com')",
        "email": { ".validate": "newData.isString() && newData.val().toLowerCase() == auth.token.email.toLowerCase()" }
      }
    },
    "guests": {
      ".read": "auth != null",
      "$uid": {
        ".write": "auth.uid == $uid && !auth.token.email.contains('@example.com')"
      }
    }
  }
}

{
  "rules": {
    "status": {
      ".read": "auth != null",
      "$uid": {
        // Each client writes its own presence, onDisconnect included.
        ".write": "auth != null && auth.uid == $uid",
        ".validate": "newData.hasChildren(['state', 'last_changed'])",
        "state": { ".validate": "newData.val() == 'online' || newData.val() == 'offline'" },
        "last_changed": { ".validate": "newData.isNumber() && newData.val() <= now + 60000" },
        "$other": { ".validate": false }
      }
    },
    "connections": {
      "$uid": {
        ".read": "auth.uid == $uid",
        "$connectionId": {
          ".write": "auth.uid == $uid",
          ".validate": "newData.val() === true"
        }
      }
    }
  }
}

{
  "rules": {
    "scores": {
      ".read": true,
      ".indexOn": ".value",
      "$uid": {
        // A score only goes up.
        ".write": "auth.uid === $uid",
        ".validate": "newData.isNumber() && newData.val() % 1 === 0 && (!data.exists() || newData.val() >= data.val())"
      }
    },
    "likes": {
      "$postId": {
        ".read": true,
        // The counter moves by exactly one.
        ".write": "auth != null",
        ".validate": "newData.isNumber() && (data.exists() ? newData.val() === data.val() + 1 || newData.val() === data.val() - 1 : newData.val() === 1)"
      }
    },
    "stats": {
      ".read": true,
      "average": {
        ".write": "auth != null",
        ".validate": "newData.val() === root.child('stats/sum').val() / root.child('stats/count').val()"
      }
    }
  }
}

{
  "rules": {
    "listings": {
      // Users list only their own listings, through a query.
      ".read": "auth != null && query.orderByChild == 'owner' && query.equalTo == auth.uid",
      ".indexOn": ["owner", "price"],
      "$listingId": {
        ".read": "data.child('public').val() === true",
        ".write": "auth != null && (!data.exists() || data.child('owner').val() == auth.uid)",
        ".validate": "newData.child('owner').val() == auth.uid && newData.child('price').isNumber()"
      }
    },
    "feed": {
      // Public feed, at most 50 at a time.
      ".read": "query.orderByKey && query.limitToLast <= 50",
      ".write": false
    }
  }
}

{
  "rules": {
    "whitelist": {
      ".read": false,
      ".write": false
    },
    "users": {
      "$uid": {
        ".read": "true",
        // The reference's example: dots are not allowed in keys, so emails are stored with %2E.
        ".write": "auth.uid == $uid && root.child('whitelist').child(newData.child('email').val().replace('.', '%2E')).exists()",
        "email": { ".validate": "newData.isString() && newData.val().matches(/^[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,4}$/i)" }
      }
    }
  }
}

{
  "rules": {
    "games": {
      "$gameId": {
        ".read": "auth != null && (data.child('players/x').val() == auth.uid || data.child('players/o').val() == auth.uid)",
        "players": {
          ".write": "auth != null && !data.exists()",
          ".validate": "newData.hasChildren(['x', 'o']) && newData.child('x').val() != newData.child('o').val()"
        },
        "turn": {
          // Players alternate, and only the player whose turn it was may hand it over.
          ".write": "data.parent().child('players').child(data.val()).val() == auth.uid",
          ".validate": "newData.val() == (data.val() == 'x' ? 'o' : 'x')"
        },
        "board": {
          "$cell": {
            ".write": "!data.exists() && root.child('games/' + $gameId + '/players/' + newData.val()).val() == auth.uid && newData.parent().parent().child('turn').val() == newData.val()",
            ".validate": "newData.val() == 'x' || newData.val() == 'o'"
          }
        },
        "moves": {
          ".write": "auth != null",
          ".validate": "newData.isNumber() && newData.val() == (data.exists() ? data.val() : 0) + 1 && newData.val() <= 9"
        }
      }
    }
  }
}

{
  "rules": {
    "uploads": {
      "$uid": {
        ".read": "auth.uid === $uid",
        "$fileId": {
          ".write": "auth.uid === $uid",
          ".validate": "newData.hasChildren(['name', 'size', 'contentType'])",
          "name": { ".validate": "newData.isString() && newData.val().matches(/^[\\w\\-. ]+\\.(png|jpe?g|gif)$/i)" },
          "size": { ".validate": "newData.isNumber() && newData.val() > 0 && newData.val() < 5 * 1024 * 1024" },
          "contentType": { ".validate": "newData.isString() && newData.val().beginsWith('image/')" },
          "path": { ".validate": "newData.val() == 'images/' + $uid + '/' + $fileId" },
          "$other": { ".validate": false }
        }
      }
    }
  }
}

{
  "rules": {
    "tenants": {
      "$tenantId": {
        // Members of a tenant, signed in with a real account, see and edit its data.
        ".read": "auth.token.tenantId === $tenantId",
        ".write": "auth.token.tenantId === $tenantId && auth.token.firebase.sign_in_provider != 'anonymous'",
        "settings": {
          ".write": "auth.token.tenantId === $tenantId && auth.token.roleMap[$tenantId] === 'owner'"
        },
        "projects": {
          "$projectId": {
            ".validate": "newData.child('tenant').val() === $tenantId"
          }
        }
      }
    }
  }
}

{
  "rules": {
    "users": {
      ".read": "auth != null",
      "$uid": {
        ".write": "auth.uid == $uid"
      }
    },
    "friends": {
      "$uid": {
        ".read": "auth.uid == $uid",
        "$friendId": {
          // Both ends of a friendship are written together, in one update.
          ".write": "auth.uid == $uid || auth.uid == $friendId",
          ".validate": "root.child('users/' + $friendId).exists() && $friendId != $uid && (!newData.exists() || newData.parent().parent().child($friendId).child($uid).exists())"
        }
      }
    },
    "requests": {
      "$to": {
        "$from": {
          ".read": "auth.uid == $to || auth.uid == $from",
          ".write": "auth.uid == $from && !root.child('friends/' + $to + '/' + $from).exists()",
          ".validate": "newData.isNumber()"
        }
      }
    }
  }
}

{
  "rules": {
    "orders": {
      ".indexOn": ["customer", "status"],
      "$orderId": {
        ".read": "auth != null && (data.child('customer').val() == auth.uid || auth.token.staff == true)",
        // Customers create orders; staff move them along.
        ".write": "auth != null && ((!data.exists() && newData.child('customer').val() == auth.uid) || auth.token.staff == true)",
        ".validate": "newData.hasChildren(['customer', 'items', 'total', 'status'])",
        "items": {
          ".validate": "newData.hasChildren()",
          "$itemId": {
            ".validate": "newData.hasChildren(['sku', 'qty']) && newData.child('qty').isNumber() && newData.child('qty').val() > 0"
          }
        },
        "total": { ".validate": "newData.isNumber() && newData.val() > 0" },
        "status": { ".validate": "newData.isString() && newData.val().matches(/^(pending|paid|shipped|cancelled)$/) && (auth.token.staff == true || newData.val() == 'pending')" },
        "note": { ".validate": "newData.isString() && newData.val().length <= 140" }
      }
    }
  }
}

{
  "rules": {
    "polls": {
      ".read": true,
      "$pollId": {
        ".write": "auth != null && !data.exists()",
        ".validate": "newData.hasChildren(['question', 'closesAt']) && newData.child('closesAt').val() > now"
      }
    },
    "votes": {
      "$pollId": {
        ".read": true,
        "$uid": {
          // One vote per user, while the poll is open; a vote cannot be changed.
          ".write": "auth != null && auth.uid == $uid && !data.exists() && root.child('polls').child($pollId).child('closesAt').val() > now",
          ".validate": "newData.isString() && root.child('polls/' + $pollId + '/options/' + newData.val()).exists()"
        }
      }
    }
  }
}

{
  "rules": {
    "products": {
      "$key1": {
        ".validate": "newData.hasChildren(['name', 'price', 'tags'])",
        "name": {
          ".validate": "newData.isString() && newData.val().length > 0 && newData.val().length <= 100"
        },
        "price": {
          ".validate": "newData.isNumber() && newData.val() >= 0"
        },
        "tags": {
          "$key2": {
            ".validate": "newData.isString() && newData.val().length <= 20"
          },
          ".validate": "newData.hasChildren()"
        },
        "discount": {
          ".validate": "(newData.isNumber() && newData.val() >= 0 && newData.val() <= 100) || newData.isString() && newData.val().endsWith('%')"
        },
        "$other": {
          ".validate": "false"
        },
        ".read": "true",
        ".write": "auth != null && auth.uid != null && (auth.token.admin == true || data.val() == null)"
      }
    }
  }
}
